class Session:
    def __init__(self, l2):
        self.l2 = l2
        self.l1 = {}
    def query(self, key):
        if key in self.l1:
            return ("L1", self.l1[key])
        if key in self.l2:
            v = self.l2[key]
            self.l1[key] = v
            return ("L2", v)
        v = "row:" + key
        self.l1[key] = v
        self.l2[key] = v
        return ("DB", v)

l2 = {}
s1 = Session(l2)
print("s1 第一次:", s1.query("u1"))
print("s1 第二次(同session):", s1.query("u1"))
s2 = Session(l2)
print("s2 第一次(新session):", s2.query("u1"))
s3 = Session(l2)
print("s3 第一次:", s3.query("u2"))
